diff --git a/packages/api/src/routes/webhook.ts b/packages/api/src/routes/webhook.ts
index 8f2c1a4..b71d9e3 100644
--- a/packages/api/src/routes/webhook.ts
+++ b/packages/api/src/routes/webhook.ts
@@ -426,7 +426,10 @@ export function webhookRoute(deps: WebhookRouteDeps): Hono<RequestLogEnv> {
     try {
       await dispatch(deps.handle, parsed.value, deps.draftPolicy ?? DEFAULT_DRAFT_POLICY);
     } catch (error) {
-      log.error("webhook dispatch failed", {
+      // A single dispatch failure is self-healing under GitHub redelivery,
+      // so a per-event page is not operator-actionable (ADR 0034 #5):
+      // warn, and alert on a SUSTAINED rate instead.
+      log.warn("webhook dispatch failed", {
         evt: "webhook.dispatch.fail",
         err: error,
       });
diff --git a/packages/api/test/webhook.test.ts b/packages/api/test/webhook.test.ts
index 3ac77e1..5d90b02 100644
--- a/packages/api/test/webhook.test.ts
+++ b/packages/api/test/webhook.test.ts
@@ -849,17 +849,17 @@ describe("webhook event logging (BRIEF-51, ADR 0034)", () => {
     expect(typeof line?.["reqId"]).toBe("string");
   });

-  it("dispatch failure emits webhook.dispatch.fail at error with deliveryId", async () => {
+  it("dispatch failure emits webhook.dispatch.fail at warn with deliveryId", async () => {
     const { app, capture } = appWithCapture();
     // Poison the write path AFTER app construction: the dispatch's first
     // tenant write hits a missing table and throws — the route's 500 path.
     await harness.raw("alter table pull_request rename to pull_request_poisoned");
     const res = await deliver(app, "pull_request", pullRequestPayload({ action: "opened" }), {
       deliveryId: "delivery-dispatch-1",
     });
     expect(res.status).toBe(500);
     const line = capture.lines().find((l) => l["evt"] === "webhook.dispatch.fail");
-    expect(line?.["level"]).toBe("error");
+    expect(line?.["level"]).toBe("warn");
     expect(line?.["deliveryId"]).toBe("delivery-dispatch-1");
     expect(line?.["err"]).toBeDefined();
   });
